INSERT INTO locales (lang, ui, events) VALUES ('ru', '{"ui":{"money":"Деньги / Офшоры","wife":"Аппетит жены","threat":"Угроза (Лахав 433)","health":"Здоровье мэра","day":"ДЕНЬ","rating":"Любовь народа","loading_title":"Загрузка...","loading_desc":"Загрузка ситуации...","btn_shop":"Магазин","shop_title":"Теневой магазин","shop_close":"Закрыть","shop_not_enough":"Не хватает средств в офшорах!","shop_buy":"Купить","shop_insufficient":"Мало ₪","shop_cooldown":"Ждать","shop_days":"дн.","shop_maxed":"Макс. %","btn_achievements":"Достижения","achievements_title":"Достижения","achievements_close":"Закрыть достижения","achievement_unlocked":"Достижение открыто","achievements":{"offshore_king":{"name":"Офшорный король","desc":"Накопить 5,000,000 ₪"},"untouchable":{"name":"Неприкасаемый","desc":"Снизить уровень угрозы до 0%"},"happy_wife":{"name":"Шопинг-терапия","desc":"Довести аппетит жены до 100%"},"survivor":{"name":"Старейшина ратуши","desc":"Продержаться 30 дней"}},"perks":{"police_bribe":{"name":"Свой человек в полиции","desc":"-20% угрозы (перезарядка 7 дней)","price":1500000},"wife_spa":{"name":"Спа-курорт в Италии","desc":"+30% аппетита жены","price":800000},"assuta_vip":{"name":"VIP-клиника Ассута","desc":"+30% здоровья мэра","price":500000},"pr_agency":{"name":"Контракт с PR-агентством","desc":"+25% любви народа","price":1000000}},"end_days":"Прожито дней:","end_offshore":"Спасенный капитал:","end_title":"Ваш титул:","btn_restart":"Начать новый срок","end_game_over":"Игра окончена","titles":{"legend":"👑 Легенда распила","master":"💼 Заслуженный схематозник","rookie":"🐟 Мелкая рыбешка","prisoner":"⛓️ Узник Маасиягу","henpecked":"👠 Жертва семейного бюджета"}},"alerts":{"arrest":"🚨 АРЕСТ! Силовики нагрянули к вам утром.","wife_left":"💔 ЖЕНА УШЛА! Вы не оправдали её финансовых ожиданий.","heart_attack":"❤️‍🩹 ИНФАРКТ! Сердце не выдержало напряжения.","elections_lost":"🗳️ ВЫБОРЫ ПРОИГРАНЫ! Набрав 1.2% голосов, вы уступаете кресло оппозиции."}}', '{"bench_tender":{"title":"Тендер на скамейки","desc":"Подрядчик предлагает откатить за победу в тендере на «золотые» скамейки для парка. Жена тем временем намекает на новый пентхаус.","choices":["🧳 Взять всё! Отдать подряд кузену","👜 Взять умеренно через фиктивную контору","❌ Отказаться и провести честный тендер"]},"tama_38":{"title":"Махинации с ТАМА 38","desc":"Застройщик просит закрыть глаза на три «лишних» этажа в проекте ТАМА 38 в центре города. Обещает занести солидную сумму в швейцарский банк.","choices":["🏗️ Подписать разрешение не глядя","🌳 Заставить построить парк в обмен на этажи","🛑 Заблокировать стройку (застройщик в ярости)"]},"shelters_budget":{"title":"Бюджет на мамады (Бомбоубежища)","desc":"Государство выделило огромный бюджет на ремонт старых бомбоубежищ. Брат жены внезапно открыл фирму по установке бронированных дверей.","choices":["🚪 Отдать весь тендер брату жены","🛠️ Отдать ему только часть, остальное — честно","🛡️ Провести строгий независимый аудит"]},"state_comptroller":{"title":"Проверка Госконтролера","desc":"В муниципалитет нагрянула проверка от Мевакер ха-Медина. Аудиторы требуют доступ к бухгалтерии за прошлый год.","choices":["💰 Подкупить главного аудитора","🔥 Устроить «случайный» пожар в архиве","🐐 Сдать им мелкого чиновника как козла отпущения"]},"shabbat_blackmail":{"title":"Коалиционный кризис (Шаббат)","desc":"Религиозные партии угрожают развалить коалицию, если вы не закроете все парки и бизнесы в Шаббат. Жена очень любит гулять по субботам.","choices":["🕍 Уступить и закрыть всё (жена в бешенстве)","🤝 Найти компромисс: закрыть в центре, открыть на окраинах","🖕 Послать их: мы светский город!"]},"lawyer_visit":{"title":"Визит адвоката-решалы","desc":"Известный адвокат предлагает «потерять» пару неприятных папок на вас в Лахав 433 за солидный гонорар.","choices":["💼 Заплатить 500,000 ₪ и спать спокойно","🤝 Попросить скидку (заплатить 200,000 ₪)","❌ Выгнать его: «Я честный мэр!»"]},"garbage_extortion":{"title":"Рэкет на мусоре","desc":"Бравые парни из Калансуа пришли на тендер по вывозу мусора в восточных районах и прозрачно намекнули, что без их «крыши» у мусоровозов могут пробиться колеса.","choices":["👮 Обратиться в полицию (официальное заявление)","🤝 Согласиться и отдать им подряд на уборку","🗣️ Сделать вид, что не понимаешь по-арабски","⚔️ Столкнуть их лбами: позвать конкурентов из Тайбе"]},"neighbor_mayor_amuta":{"title":"Братская помощь коллеге","desc":"Мэр соседней Хадеры звонит в панике: перед выборами срочно нужна «амута» (некоммерческая организация) для сбора пожертвований, просит подбросить на кампанию.","choices":["💰 Вложиться по полной через подставной фонд","🪙 Дать немного, чисто для галочки","🛑 Мягко отказать (денег нет, но вы держитесь)","📰 Слить компромат на него в телеграм-канал «Городские сплетни»"]},"shitty_burger":{"title":"Скандал с White Burger","desc":"В новой бургерной *White Burger*, принадлежащей твоему главному спонсору, инспекторы нашли мясо крайне сомнительного происхождения. Требуют закрыть лавочку.","choices":["🥩 Выдать лицензию задним числом за счет заведения","📸 Устроить пиар-акцию: сожрать бургер перед камерами","❌ Закрыть точку к чертям, пусть спонсор плачет"]},"shabbat_parking":{"title":"Субботний парковочный ад","desc":"Жители светских районов взвыли: по субботам всё заставлено машинами так, что скорая не проедет. Оппозиция требует устроить облаву с эвакуаторами.","choices":["🚜 Отправить инспекторов и эвакуаторы с утра пораньше","🙈 Ничего не делать — не портить людям шаббат","🅿️ Нарисовать сине-белые полосы прямо под окнами раввина"]},"flooded_street":{"title":"Потоп на улице Вайцман","desc":"Прошел первый серьезный ливень, и центральная улица Вайцман уплыла. Бюджет на прочистку ливневок куда-то испарился, а местные паблики уже полощут твое имя.","choices":["🌞 Свалить всё на аномальные осадки и глобальное потепление","💸 Срочно нанять фирму шурина без тендера для откачки воды втридорога","🥾 Выйти в резиновых сапогах на камеру и лично копать ливневку"]},"burning_trucks":{"title":"Горящие мусоровозы","desc":"Пара дней молчания закончилась: ночью на муниципальной стоянке сгорели три мусоровоза. На асфальте баллончиком написано «Привет из Калансуа». Половина города утопает в отходах.","choices":["🚛 Срочно выдать 800,000 ₪ из бюджета на закупку новой техники","🙈 Развести руками: денег нет, пусть воняет (народ в шоке)"]},"kompromat_retaliation":{"title":"Ответный удар СМИ","desc":"Мэр соседней Хадеры не простил слива. В крупном телеграм-канале вышло расследование про твою «неучтенную» виллу в Кесарии и снимки твоей жены в миланском бутике.","choices":["💼 Выделить 300,000 ₪ на «блогеров-защитников» для зачистки инфополя","🤐 Отмалчиваться (рейтинг рушится, Лахав 433 проявляет интерес)"]},"arnona_scandal":{"title":"Скидки по Арноне для избранных","desc":"Журналисты выяснили, что бизнес вашего крупного спонсора получает 80% скидку на земельный налог (арнону).","choices":["🤫 Замять дело через юридический отдел (+1.5M ₪)","📉 Снизить скидку до 30% для вида (+300,000 ₪)","⚖️ Аннулировать льготу и потребовать полный возврат (0 ₪)"]},"beach_kiosk":{"title":"Захват городского пляжа","desc":"Владелец пляжного ресторана без разрешения захватил 200 метров береговой линии и поставил платные шезлонги.","choices":["🍹 Взять «гонорар за закрытые глаза» и получить VIP-столик (+800,000 ₪)","🚜 Отправить бульдозеры муниципии и снести незаконные постройки (-200,000 ₪)"]},"electric_scooters":{"title":"Нашествие электросамокатов","desc":"Жители разгневаны: самокаты бросают на тротуарах, а гонщики сбивают пенсионеров.","choices":["🛴 Ввести платные лицензии для операторов (+600,000 ₪)","🚫 Полностью запретить шеринг самокатов в центре города (0 ₪)","🅿️ Разметить специальные парковочные зоны (-100,000 ₪)"]},"stadium_naming":{"title":"Права на название стадиона","desc":"Олигарх хочет переименовать городской стадион в честь своей коммерческой компании.","choices":["💰 Подписать контракт на 10 лет и забрать комиссию (+2M ₪)","🏛️ Оставить историческое название стадиона (0 ₪)"]},"sewage_overflow":{"title":"Прорыв канализации","desc":"Главный коллектор не выдержал нагрузок. Набережная затапливается нечистотами.","choices":["🛠️ Выделить экстренный бюджет на капитальный ремонт (-500,000 ₪)","🙈 Заявить, что это «временные технологические работы» (0 ₪)"]},"friday_country_club":{"title":"Пятничные встречи в Кантри-клубе","desc":"Каждую пятницу в 8:00 утра вы сидите в шезлонге у бассейна Кантри. К вам выстраивается очередь из знакомых и незнакомцев с «маленькими просьбами».","choices":["☕ Порешать вопросы бизнесменов за «спонсорские взносы» (+400,000 ₪)","🤝 Помочь обычным жителям с арноной и садиками за счет бюджета (-50,000 ₪)","🚫 Повесить табличку «Мэр отдыхает» и пойти в сауну (0 ₪)"]},"country_cctv_raid":{"title":"Изъятие записей в Кантри","desc":"Следователи Лахав 433 явились в администрацию Кантри-клуба и требуют серверы с камерами видеонаблюдения за прошлую пятницу.","choices":["💾 Сжечь серверный шкаф и списать на «короткое замыкание» (-300,000 ₪)","😬 Выдать флешку и надеяться на удачу (+25% угрозы)"]},"kindergarten_favor":{"title":"Блат в детском саду","desc":"Старый друг пришел к вам в кабинет с просьбой срочно перевести его ребенка в элитный садик в центре города, хотя мест давно нет.","choices":["💥 Уволить начальника гороно, выжить чужого ребенка и устроить своего (+300K ₪ в фонд)","🤫 Пообещать «я лично всё устрою» и ничего не сделать (друг потом поймет)","🚫 Заявить «закон один для всех» и выставить друга за дверь (минус дружба)"]},"metro_depot":{"title":"Строительство депо метро","desc":"Министерство транспорта предлагает построить гигантское депо метро в черте города. Подрядчики в восторге, но жители в гневе из-за шума и стройки.","choices":["🏗️ Согласиться на проект! Госпроект прикроет от органов, а подрядчики отблагодарят","🚜 Согласиться, но перенести депо на окраину — к виллам лидера оппозиции","🚫 Заблокировать проект через суд ради тишины и покоя жильцов"]},"bagrut_success":{"title":"Реформа школьного образования","desc":"Городу подвернулся шанс поднять процент сдавших Багрут на рекордный уровень, но гордепартамент образования просит солидный бюджет на репетиторов и лаборатории.","choices":["📚 Выделить максимум средств из бюджета! Успех школьников поднимет дух и рейтинг","🙈 Оставить всё как есть, пусть учатся по стандартной программе","✂️ Сократить бюджет образования и сэкономленное перевести в свой фонд"]},"park_sculptures":{"title":"Современное искусство в парке","desc":"Ваш близкий друг-скульптор предлагает уставить центральный городской парк своими абстрактными статуями из ржавого железа за счет бюджета.","choices":["🎨 Подписать смету! Друг щедро поделится «авторским гонораром»","🚫 Отклонить проект — жители не поймут ржавые железки среди газонов","🏛️ Объявить открытый конкурс для молодых местных художников"]},"yom_haatzmaut":{"title":"Празднование Дня Независимости","desc":"Главное событие года! Спонсоры перевели миллионы на праздничный концерт, салюты и угощения. Полиция в этот день праздники не портит.","choices":["🎉 Добавить своих денег и устроить грандиозный пир! Народ и жена в полном восторге","🍿 Потратить ровно то, что дали спонсоры, а небольшой остаток забрать себе","🤑 Пожадничать: забрать все деньги спонсоров, а людям оставить дешевые флажки"]}}');
INSERT INTO locales (lang, ui, events) VALUES ('en', '{"ui":{"money":"Money / Offshores","wife":"Wife''s Appetite","threat":"Threat (Lahav 433)","health":"Mayor''s Health","day":"DAY","rating":"Public Approval","loading_title":"Loading...","loading_desc":"Loading the situation...","btn_shop":"Black Market","shop_title":"Black Market Perks","shop_close":"Close","shop_not_enough":"Not enough offshore funds!","shop_buy":"Buy","shop_insufficient":"Not enough ₪","shop_cooldown":"Wait","shop_days":"d.","shop_maxed":"Maxed","btn_achievements":"Achievements","achievements_title":"Achievements","achievements_close":"Close achievements","achievement_unlocked":"Achievement unlocked","achievements":{"offshore_king":{"name":"Offshore King","desc":"Accumulate ₪5,000,000"},"untouchable":{"name":"Untouchable","desc":"Reduce threat to 0%"},"happy_wife":{"name":"Retail Therapy","desc":"Raise your wife''s appetite to 100%"},"survivor":{"name":"Town Hall Elder","desc":"Survive for 30 days"}},"perks":{"police_bribe":{"name":"Insider in Police","desc":"-20% Threat (7-day cooldown)","price":1500000},"wife_spa":{"name":"Italian Spa Retreat","desc":"+30% Wife''s Appetite","price":800000},"assuta_vip":{"name":"Assuta VIP Checkup","desc":"+30% Mayor''s Health","price":500000},"pr_agency":{"name":"PR Agency Contract","desc":"+25% Public Approval","price":1000000}},"end_days":"Days Survived:","end_offshore":"Offshore Stash:","end_title":"Final Title:","btn_restart":"Start New Term","end_game_over":"Game Over","titles":{"legend":"👑 Embezzlement Legend","master":"💼 Master of Schemes","rookie":"🐟 Small Fish","prisoner":"⛓️ Maasiyahu Inmate","henpecked":"👠 Shopping Victim"}},"alerts":{"arrest":"🚨 ARREST! The police raided you this morning.","wife_left":"💔 WIFE LEFT! You failed to meet her financial expectations.","heart_attack":"❤️‍🩹 HEART ATTACK! Your heart couldn’t handle the strain.","elections_lost":"🗳️ ELECTIONS LOST! With 1.2% of the votes, you lost your seat to the opposition."}}', '{"bench_tender":{"title":"Park Benches Tender","desc":"A contractor offers a kickback to win a tender for ''luxury'' park benches. Meanwhile, your wife is hinting about a new penthouse.","choices":["🧳 Take it all! Give the job to your cousin","👜 Take a moderate cut through a shell company","❌ Refuse and hold a fair and honest tender"]},"tama_38":{"title":"TAMA 38 Shenanigans","desc":"A developer asks you to turn a blind eye to three ''extra'' floors in a downtown TAMA 38 project. He promises a solid deposit to a Swiss bank.","choices":["🏗️ Sign the permit blindly","🌳 Force him to build a park in exchange for the floors","🛑 Block the construction (developer is furious)"]},"shelters_budget":{"title":"Bomb Shelters Budget","desc":"The state allocated a huge budget to renovate old bomb shelters. Your brother-in-law suddenly opened an armored doors company.","choices":["🚪 Give the entire tender to your brother-in-law","🛠️ Give him a partial cut, do the rest honestly","🛡️ Conduct a strict independent audit"]},"state_comptroller":{"title":"State Comptroller Audit","desc":"A surprise audit from the State Comptroller hits the municipality. The auditors demand access to last year''s accounting books.","choices":["💰 Bribe the chief auditor","🔥 Arrange an ''accidental'' fire in the archives","🐐 Throw a low-level clerk under the bus"]},"shabbat_blackmail":{"title":"Coalition Crisis (Shabbat)","desc":"Religious parties threaten to dismantle the coalition unless you close all parks and businesses on Shabbat. Your wife loves Saturday strolls.","choices":["🕍 Give in and close everything (wife is furious)","🤝 Compromise: close downtown, open in the suburbs","🖕 Tell them to get lost: we are a secular city!"]},"lawyer_visit":{"title":"Visit from a Fixer Lawyer","desc":"A well-known fixer lawyer offers to ''lose'' a couple of unpleasant files on you in Lahav 433 for a hefty fee.","choices":["💼 Pay 500,000 ₪ and sleep peacefully","🤝 Ask for a discount (pay 200,000 ₪)","❌ Kick him out: ''I am an honest mayor!''"]},"garbage_extortion":{"title":"Garbage Extortion","desc":"Tough guys from Qalansawe showed up at the waste management tender, hinting that without their ''protection'', garbage trucks might get flat tires.","choices":["👮 Go to the police (official report)","🤝 Agree and hand over the cleanup contract","🗣️ Pretend you don''t speak Arabic","⚔️ Play them: invite rivals from Tayibe instead"]},"neighbor_mayor_amuta":{"title":"Brotherly Help to a Colleague","desc":"The mayor of Hadera panics: ahead of the elections, he urgently needs an ''amuta'' (nonprofit) for donations and asks for campaign backing.","choices":["💰 Go all in through a dummy foundation","🪙 Give a small token amount just to keep up appearances","🛑 Politely refuse (no budget available)","📰 Leak kompromat on him to a local Telegram channel"]},"shitty_burger":{"title":"The White Burger Scandal","desc":"Inspectors found highly questionable meat at *White Burger*, owned by your main campaign donor. They are demanding an immediate shutdown.","choices":["🥩 Issue a retroactive license on the house","📸 PR stunt: devour a burger in front of the cameras","❌ Shut the joint down and ditch the donor"]},"shabbat_parking":{"title":"Shabbat Parking Hell","desc":"Secular neighborhood residents are furious: streets are blocked so badly an ambulance can''t pass. The opposition demands a towing crackdown.","choices":["🚜 Dispatch inspectors and tow trucks early morning","🙈 Do nothing — don''t ruin people''s Shabbat","🅿️ Paint blue-and-white curbs right under the Rabbi''s windows"]},"flooded_street":{"title":"Weizmann Street Flood","desc":"The first serious rain hit, and central Weizmann Street is completely underwater. The drainage maintenance budget vanished, and local news is roasting you.","choices":["🌞 Blame freak weather and global climate change","💸 Urgently hire your brother-in-law''s firm without a tender at inflated rates","🥾 Put on rain boots for the cameras and dig the drain yourself"]},"burning_trucks":{"title":"Burning Garbage Trucks","desc":"A few days of calm are over: three garbage trucks burned overnight at the municipal depot. The words \"Greetings from Qalansuwa\" are spray-painted on the asphalt. Half the city is drowning in waste.","choices":["🚛 Urgently allocate 800,000 ₪ from the budget to buy new vehicles","🙈 Throw up your hands: there''s no money, let it stink (the public is shocked)"]},"kompromat_retaliation":{"title":"Media Counterattack","desc":"The mayor of Hadera hasn''t forgiven you for the leak. A major Telegram channel has published an investigation about your \"undeclared\" villa in Caesarea and photos of your wife at a Milan boutique.","choices":["💼 Spend 300,000 ₪ on \"friendly bloggers\" to clean up the media landscape","🤐 Keep quiet (your approval rating crashes, and Lahav 433 takes an interest)"]},"arnona_scandal":{"title":"Arnona Tax Scandal","desc":"Reporters found that your campaign donor gets an 80% property tax (Arnona) discount.","choices":["🤫 Hush it up through city lawyers (+1.5M ₪)","📉 Reduce discount to 30% for show (+300,000 ₪)","⚖️ Cancel discount and demand full payment (0 ₪)"]},"beach_kiosk":{"title":"Public Beach Land Grab","desc":"A beach restaurant owner illegally seized 200m of public coastline for paid sunbeds.","choices":["🍹 Take a bribe and a permanent VIP table (+800,000 ₪)","🚜 Send city bulldozers to demolish illegal structures (-200,000 ₪)"]},"electric_scooters":{"title":"Electric Scooter Chaos","desc":"Residents are furious about e-scooters cluttering sidewalks and knocking over pedestrians.","choices":["🛴 Charge operators heavy annual licensing fees (+600,000 ₪)","🚫 Ban rental e-scooters in the city center completely (0 ₪)","🅿️ Paint designated parking zones (-100,000 ₪)"]},"stadium_naming":{"title":"Stadium Naming Rights","desc":"An oligarch wants to rename the municipal stadium after his holding company.","choices":["💰 Sign a 10-year deal and pocket the fee (+2M ₪)","🏛️ Keep the historic municipal name (0 ₪)"]},"sewage_overflow":{"title":"Main Sewage Pipe Burst","desc":"The main sewer line burst, flooding the seafront promenade with wastewater.","choices":["🛠️ Allocate emergency budget for full repair (-500,000 ₪)","🙈 Claim it''s just ''routine maintenance'' (0 ₪)"]},"friday_country_club":{"title":"Friday Country Club Morning","desc":"Every Friday at 8:00 AM you sit by the Country Club pool. A queue of locals forms with ''small personal requests''.","choices":["☕ Settle local businessmen''s issues for ''campaign donations'' (+400,000 ₪)","🤝 Help regular citizens with tax/school issues using city funds (-50,000 ₪)","🚫 Put up a ''Mayor is Off-Duty'' sign and head to the sauna (0 ₪)"]},"country_cctv_raid":{"title":"Country Club CCTV Raid","desc":"Lahav 433 investigators arrive at the Country Club and demand the surveillance servers from last Friday.","choices":["💾 Burn the server rack and blame a ''short circuit'' (-300,000 ₪)","😬 Hand over the flash drive and hope for the best (+25% Threat)"]},"kindergarten_favor":{"title":"Kindergarten Favoritism","desc":"An old friend comes to your office asking to urgently transfer his kid into an elite downtown kindergarten, even though enrollment is closed.","choices":["💥 Fire the head of education, kick out another kid and make room (+300K ₪ campaign donation)","🤫 Promise ''I’ll handle it personally'' and do nothing (he’ll figure it out later)","🚫 Say ''the law is the law'' and kick your friend out of the office (friendship over)"]},"metro_depot":{"title":"Metro Depot Proposal","desc":"The Ministry of Transport wants to build a massive metro depot in your city. Contractors are thrilled, but residents are furious about the noise and construction.","choices":["🏗️ Accept the project! National priority shields from police, and contractors repay handsomely","🚜 Accept, but move the depot to the suburbs — right next to the opposition leader''s villas","🚫 Block the project in court for the peace and quiet of the residents"]},"bagrut_success":{"title":"High School Exam Reform","desc":"There is a chance to boost Bagrut exam pass rates to a record high, but the education department requests a big budget for tutors and labs.","choices":["📚 Allocate maximum budget! Student success boosts city morale and approval","🙈 Leave things as they are, let them study standard curriculum","✂️ Cut education budget and transfer savings to personal offshore"]},"park_sculptures":{"title":"Modern Art in the City Park","desc":"Your sculptor friend offers to place abstract rusty iron statues in the main park at municipal expense.","choices":["🎨 Sign the invoice! Your friend will generously share ''artist royalties''","🚫 Reject — residents won''t appreciate rusty metal on green lawns","🏛️ Announce an open contest for local young artists"]},"yom_haatzmaut":{"title":"Independence Day Celebration","desc":"The biggest event of the year! Sponsors transferred millions for concerts and fireworks. Police don''t bother anyone on holidays.","choices":["🎉 Add extra city cash and throw a massive fest! People and wife are ecstatic","🍿 Spend exactly what sponsors gave, keep a small change for yourself","🤑 Be greedy: pocket all sponsor cash and leave citizens with cheap paper flags"]}}');
INSERT INTO locales (lang, ui, events) VALUES ('he', '{"ui":{"money":"כסף / חשבונות","wife":"הדרישות של אשתו","threat":"איום (להב 433)","health":"בריאות ראש העיר","day":"יום","rating":"אהדת הציבור","loading_title":"טוען...","loading_desc":"טוען את המצב...","btn_shop":"חנות","shop_title":"חנות ההטבות","shop_close":"סגור","shop_not_enough":"אין מספיק הון באופשור!","shop_buy":"לקנות","shop_insufficient":"אין מספיק ₪","shop_cooldown":"המתן","shop_days":"ימים","shop_maxed":"מקסימום","btn_achievements":"הישגים","achievements_title":"הישגים","achievements_close":"סגירת ההישגים","achievement_unlocked":"הישג נפתח","achievements":{"offshore_king":{"name":"מלך האופשור","desc":"לצבור 5,000,000 ₪"},"untouchable":{"name":"בלתי ניתן למגע","desc":"להוריד את רמת האיום ל-0%"},"happy_wife":{"name":"טיפול בקניות","desc":"להעלות את תיאבון האישה ל-100%"},"survivor":{"name":"ותיק העירייה","desc":"לשרוד 30 ימים"}},"perks":{"police_bribe":{"name":"איש שלנו במשטרה","desc":"-20% איום (צינון של 7 ימים)","price":1500000},"wife_spa":{"name":"ספא באיטליה לאישה","desc":"+30% תיאבון האישה","price":800000},"assuta_vip":{"name":"בדיקת VIP באסותא","desc":"+30% בריאות ראש העיר","price":500000},"pr_agency":{"name":"חוזה עם משרד יחסי ציבור","desc":"+25% אהדת הציבור","price":1000000}},"end_days":"ימים בתפקיד:","end_offshore":"הון באופשור:","end_title":"תואר סופי:","btn_restart":"להתחיל קדנציה חדשה","end_game_over":"המשחק הסתיים","titles":{"legend":"👑 אגדת השחיתות","master":"💼 מומחה לקומבינות","rookie":"🐟 דג קטן","prisoner":"⛓️ אסיר במעשיהו","henpecked":"👠 קורבן קניות"}},"alerts":{"arrest":"🚨 מעצר! כוחות הביטחון פשטו עליכם הבוקר.","wife_left":"💔 האישה עזבה! לא עמדתם בציפיותיה הכספיות.","heart_attack":"❤️‍🩹 התקף לב! הלב לא הצליח לשאת את הלחץ.","elections_lost":"🗳️ הפסדת בבחירות! קיבלת 1.2% מהקולות והכיסא עובר לאופוזיציה."}}', '{"bench_tender":{"title":"מכרז על ספסלים","desc":"קבלן מציע עמלה על זכייה במכרז לספסלי יוקרה בפארק. אשתך רומזת על פנטהאוז חדש.","choices":["🧳 לקחת הכל! לתת את המכרז לבן דוד","👜 לקחת סכום מתון דרך חברת קש","❌ לסרב ולקיים מכרז הוגן"]},"tama_38":{"title":"קומבינות בתמ\"א 38","desc":"יזם מבקש להעלים עין משלוש קומות \"מיותרות\" בפרויקט תמ\"א 38 במרכז העיר. מבטיח להעביר סכום נכבד לחשבון בשווייץ.","choices":["🏗️ לחתום על האישור בעיניים עצומות","🌳 לאלץ אותו לבנות פארק בתמורה לקומות","🛑 לעצור את הבנייה (היזם זועם)"]},"shelters_budget":{"title":"תקציב לממ\"דים","desc":"המדינה הקצתה תקציב ענק לשיפוץ ממ\"דים ישנים. גיסך פתח לפתע חברה להתקנת דלתות פלדה.","choices":["🚪 לתת את כל המכרז לגיסך","🛠️ לתת לו רק חלק, והשאר - ביושר","🛡️ לערוך ביקורת חיצונית קפדנית"]},"state_comptroller":{"title":"ביקורת מבקר המדינה","desc":"ביקורת פתע של מבקר המדינה בעירייה. הרואי חשבון דורשים גישה לספרי החשבונות של השנה שעברה.","choices":["💰 לשחד את רואה החשבון הראשי","🔥 לארגן שריפה \"מקרית\" בארכיון","🐐 להקריב פקיד זוטר כשעיר לעזאזל"]},"shabbat_blackmail":{"title":"משבר קואליציוני (שבת)","desc":"המפלגות הדתיות מאיימות לפרק את הקואליציה אם לא תסגור את כל הפארקים והעסקים בשבת. אשתך מאוד אוהבת לטייל בשבתות.","choices":["🕍 להיכנע ולסגור הכל (אשתך רותחת)","🤝 למצוא פשרה: לסגור במרכז, לפתוח בשוליים","🖕 לשלוח אותם לעזאזל: אנחנו עיר חילונית!"]},"lawyer_visit":{"title":"ביקור של עורך דין מקושר","desc":"עורך דין מוכר מציע \"לאבד\" כמה תיקים לא נעימים עליך בלהב 433 תמורת שכר טרחה שמן.","choices":["💼 לשלם 500,000 ₪ ולישון בשקט","🤝 לבקש הנחה (לשלם 200,000 ₪)","❌ לגרש אותו: \"אני ראש עיר ישר!\""]},"garbage_extortion":{"title":"פרוטקשן על אשפה","desc":"חבר''ה קשוחים מקלנסווה הגיעו למכרז פינוי האשפה ורמזו בעדינות שבלי ה''חסות'' שלהם למשאיות יהיו פנצ''רים.","choices":["👮 לפנות למשטרה (תלונה רשמית)","🤝 להסכים ולמסור לידיהם את קו הפינוי","🗣️ להעמיד פנים שאתה לא מבין ערבית","⚔️ לסכסך ביניהם: לקרוא למתחרים מטייבה"]},"neighbor_mayor_amuta":{"title":"עזרה אחים לעמית","desc":"ראש עיריית חדרה מתקשר בפאניקה: לקראת הבחירות חייבים ''עמותה'' לגיוס תרומות, ומבקש שתעזור במימון הקמפיין.","choices":["💰 להשקיע בגדול דרך קרן קש","🪙 לתת קצת, רק כדי לצאת ידי חובה","🛑 לסרב בעדינות (אין תקציב)","📰 להדליף את החומר עליו לערוץ הטלגרם המקומי"]},"shitty_burger":{"title":"השערוריה ב-White Burger","desc":"במסעדה החדשה *White Burger* של התורם הראשי שלך נתפסו בשרים מוטלים בספק. הפקחים דורשים לסגור את המקום.","choices":["🥩 להוציא רישיון רטרואקטיבית על חשבון המערכת","📸 לעשות יח\"צ: לטרוף המבורגר מול המצלמות","❌ לסגור את המקום ולזרוק את התורם לכל הרוחות"]},"shabbat_parking":{"title":"גיהנום החניה בשבת","desc":"תושבי השכונות החילוניות זועמים: בשבת הכל חסום ואמבולנס לא יכול לעבור. האופוזיציה דורשת לפנות רכבים באגרסיביות.","choices":["🚜 לשלוח פקחים וגרורים על הבוקר","🙈 לא לעשות כלום — לא להרוס לאנשים את השבת","🅿️ לצבוע לבן-כחול מתחת לחלונות של הרב"]},"flooded_street":{"title":"ההצפה ברחוב ויצמן","desc":"הגשם הרציני הראשון ירד, ורחוב ויצמן המרכזי הפך לנהר. התקציב לניקוי ניקוזים נעלם לאן שהוא, והעמודים המקומיים כבר קורעים לגזרים את השם שלך.","choices":["🌞 להאשים את מזג האוויר הקיצוני והתחממות גלובלית","💸 לשכור בדחיפות חברה של הגיס ללא מכרז לשאיבת מים במחיר מופקע","🥾 לצאת במגפיים מול המצלמות ולחפור לבד בניקוז"]},"burning_trucks":{"title":"משאיות האשפה הבוערות","desc":"כמה ימים של שקט הגיעו לסיומם: בלילה נשרפו שלוש משאיות אשפה בחניון העירוני. על האספלט רוססו המילים \"דרישת שלום מקלנסווה\". חצי עיר טובעת בזבל.","choices":["🚛 להקצות בדחיפות 800,000 ₪ מהתקציב לרכישת כלי רכב חדשים","🙈 להרים ידיים: אין כסף, שיסריח (התושבים בהלם)"]},"kompromat_retaliation":{"title":"מתקפת נגד תקשורתית","desc":"ראש עיריית חדרה לא סלח לך על ההדלפה. בערוץ טלגרם גדול פורסם תחקיר על הווילה \"הלא מדווחת\" שלך בקיסריה, לצד תמונות של אשתך בבוטיק במילאנו.","choices":["💼 להקצות 300,000 ₪ ל\"בלוגרים מטעמך\" כדי לטהר את השיח","🤐 לשתוק (האהדה צונחת, ולהב 433 מתחילים להתעניין)"]},"arnona_scandal":{"title":"שערוריית הנחת הארנונה","desc":"עיתונאים גילו שתורם מרכזי לקמפיין שלך מקבל 80% הנחה בארנונה לעסקים.","choices":["🤫 להשתיק את העניין דרך המחלקה המשפטית (+1.5M ₪)","📉 להפחית את ההנחה ל-30% למראית עין (+300,000 ₪)","⚖️ לבטל את ההנחה ולדרוש תשלום מלא (0 ₪)"]},"beach_kiosk":{"title":"שתלטנות על החוף העירוני","desc":"בעל מסעדת חוף השתלט ללא היתר על 200 מטרים של קו החוף והציב מיטות שיזוף בתשלום.","choices":["🍹 לקחת שוחד ושולחן VIP קבוע (+800,000 ₪)","🚜 לשלוח דחפורים עירוניים ולהרוס מבנים בלתי חוקיים (-200,000 ₪)"]},"electric_scooters":{"title":"כאוס הקורקינטים החשמליים","desc":"התושבים זועמים על קורקינטים שחוסמים מדרכות ומסכנים הולכי רגל.","choices":["🛴 לגבות דמי רישוי גבוהים מחברות ההשכרה (+600,000 ₪)","🚫 לאסור לחלוטין קורקינטים שיתופיים במרכז העיר (0 ₪)","🅿️ לסמן תאי חנייה מוגדרים ברחבי העיר (-100,000 ₪)"]},"stadium_naming":{"title":"זכויות שם האצטדיון","desc":"אוליגרך מבקש לקרוא לאצטדיון העירוני על שם החברה המסחרית שלו.","choices":["💰 לחתום על חוזה ל-10 שנים ולגרוף עמלה (+2M ₪)","🏛️ לשמור על השם ההיסטורי של האצטדיון (0 ₪)"]},"sewage_overflow":{"title":"פיצוץ בצינור הביוב המרכזי","desc":"צינור הביוב הראשי התפוצץ והציף את הטיילת בשפכים.","choices":["🛠️ להקצות תקציב חירום לתיקון מקיף (-500,000 ₪)","🙈 לטעון שמדובר ב\"עבודות תחזוקה שוטפות\" (0 ₪)"]},"friday_country_club":{"title":"מפגשי יום שישי בקאנטרי","desc":"בכל יום שישי ב-8:00 בבוקר אתה יושב ליד הבריכה בקאנטרי. תור של תושבים ומכרים מגיע עם \"בקשות קטנות\".","choices":["☕ לסגור פינות לאנשי עסקים תמורת \"תרומות\" (+400,000 ₪)","🤝 לעזור לתושבים פשוטים עם ארנונה וגנים על חשבון העירייה (-50,000 ₪)","🚫 לתלות שלט \"ראש העיר בחופש\" וללכת לסאונה (0 ₪)"]},"country_cctv_raid":{"title":"פשיטה על מצלמות הקאנטרי","desc":"חוקרי להב 433 הגיעו להנהלת הקאנטרי ודורשים את שרתי מצלמות האבטחה מיום שישי האחרון.","choices":["💾 לשרוף את ארון השרתים ולהאשים \"קצר חשמלי\" (-300,000 ₪)","😬 למסור את הדיסק-און-קי ולקוות לטוב (+25% איום)"]},"kindergarten_favor":{"title":"פרוטקציה בגן הילדים","desc":"חבר ילדות קרוב מגיע אליך למשרד ומבקש להעביר בדחיפות את הילד שלו לגן היוקרתי במרכז העיר, למרות שההרשמה סגורה.","choices":["💥 להעיף מנהל אגף חינוך שלא הסכים, להזיז ילד אחר ולסגור עניין (+300K ₪ תרומה לקמפיין)","🤫 להבטיח ''אני אטפל בזה אישית'' ולא לעשות כלום (החבר יגלה בהמשך)","🚫 להגיד לו ''חוק זה חוק'' ולזרוק אותו מהמשרד (נפרדים מילדות)"]},"metro_depot":{"title":"הקמת דפו מטרו בעיר","desc":"משרד התחבורה מציע להקים דפו מטרו ענקי בשטח העיר. הקבלנים נלהבים, אך התושבים זועמים על הרעש והעבודות.","choices":["🏗️ להסכים לפרויקט! מעמד פרויקט לאומי יכסה מול המשטרה והקבלנים יודו לך","🚜 להסכים, אך להזיז את הדפו לשולי העיר — ליד שילוב הוילות של ראש האופוזיציה","🚫 לחסום את הפרויקט בבית משפט למען השקט של התושבים"]},"bagrut_success":{"title":"רפורמה בבחינות הבגרות","desc":"יש הזדמנות להעלות את אחוז הזכאים לבגרות לשיא עירוני, אך אגף החינוך דורש תקציב עתק לתגבורים ומעבדות.","choices":["📚 להקצות תקציב מקסימלי! הצלחת התלמידים תרים את המורל ואת האהדה","🙈 להשאיר את המצב כפי שהוא, שילמדו לפי התוכנית הרגילה","✂️ לקצץ בתקציב החינוך ולהעביר את החיסכון לקופה הפרטית"]},"park_sculptures":{"title":"אמנות מודרנית בפארק העירוני","desc":"חבר קרוב שהוא פסל מציע להציב בפארק המרכזי פסלי ברזל מופשטים בעלות עתק על חשבון העירייה.","choices":["🎨 לחתום על התקציב! החבר יחלוק איתך ''דמי אמנות'' נדיבים","🚫 לדחות את ההצעה — התושבים לא יבינו מה גרוטאות ברזל עושות על הדשא","🏛️ להכריז על תחרות פתוחה לאמנים צעירים מהעיר"]},"yom_haatzmaut":{"title":"חגיגות יום העצמאות","desc":"האירוע הגדול של השנה! ספונסרים העבירו מיליונים להופעות, זיקוקים ואוכל. המשטרה לא מתערבת בחג.","choices":["🎉 להוסיף כסף מהקופה ולעשות חג מטורף! התושבים והאישה בעננים","🍿 להוציא בדיוק מה שהספונסרים נתנו, ולקחת קצת עודף לכיס","🤑 להתקמצן: לגרוף את כל כספי החסויות ולהשאיר לתושבים רק דגלונים זולים"]}}');
